#pragma once

#include <stdint.h>

// Bitmap fonts generated by tools/fonts2c.py. Each glyph is a cell of `height`
// rows and `advance` columns; a row is a uint16_t with the MSB as leftmost pixel.
typedef struct {
  uint8_t advance;
  uint16_t offset;  // index of the glyph's first row in font_t.rows
} font_glyph_t;

typedef struct {
  uint8_t height;
  uint8_t first;  // first Latin-1 code point covered
  uint8_t last;   // last Latin-1 code point covered
  const font_glyph_t *glyphs;
  const uint16_t *rows;
} font_t;

extern const font_t font_tb8;     // proportional, 8 px
extern const font_t font_6x13;    // 6x13 fixed
extern const font_t font_10x20;   // 10x20 fixed, big clock digits
extern const font_t font_4x5;     // CG-pixel-4x5-mono, tiny
